/// The shield sprite (index + 1) for a road's network and route-number length (1..=5).
pub fn shield_icon(network: &str, len: usize) -> u8 {
    let row: [u8; 5] = match network {
        "US:I" => [36, 37, 38, 39, 40],
        "NL:S-road" => [41, 42, 43, 44, 45],
        _ => [46, 47, 48, 49, 50],
    };
    if (1..=5).contains(&len) {
        row[len - 1]
    } else {
        0
    }
}

